const user = $('Run an Actor and get dataset').first().json.activityOfUser;

const name = `${user.firstName || ''} ${user.lastName || ''}`.trim();

const posts = $input.all().map(item => ({
  post_content: item.json.post_content,
  timeSincePosted: item.json.timeSincePosted
}));

return [
  {
    json: {
      name,
      posts
    }
  }
];

const output = String($json.output || '');

const message = output
  .replace(/\\n/g, '\n')
  .trim();

return [
  {
    json: {
      message,

    }
  }
];
